// The few parts of the Workers runtime the backend calls, beside the web APIs the "webworker"
// lib declares, written out here rather than generated by `wrangler types`, whose output
// declares the whole runtime (https://developers.cloudflare.com/d1/worker-api/).

interface D1Result<T = Record<string, unknown>> {
  results: T[]
  success: boolean
  meta: { changes: number }
}

interface D1PreparedStatement {
  bind(...values: unknown[]): D1PreparedStatement
  first<T = Record<string, unknown>>(): Promise<T | null>
  all<T = Record<string, unknown>>(): Promise<D1Result<T>>
  run(): Promise<D1Result>
}

interface D1Database {
  prepare(query: string): D1PreparedStatement
  /** Runs the statements in one transaction, which rolls back whole when one fails. */
  batch(statements: D1PreparedStatement[]): Promise<D1Result[]>
}

interface ScheduledController {
  readonly scheduledTime: number
  readonly cron: string
}
